from flask import Flask, session, request, jsonify
import os

app = Flask(__name__)
app.secret_key = os.environ['{{secret_env}}']
app.config.update(SESSION_COOKIE_HTTPONLY=True, SESSION_COOKIE_SAMESITE='Lax')

@app.post('/login')
def login():
    session['user'] = (request.get_json() or {}).get('username')
    return jsonify(ok=True)

@app.get('/me')
def me():
    return jsonify(user=session.get('user'))

@app.post('/logout')
def logout():
    session.clear()
    return jsonify(ok=True)
